request_body.query:
query getDiscountNodes(
  $first: Int
  $last: Int
  $after: String
  $before: String
  $query: String
  $reverse: Boolean
  $sortKey: DiscountSortKeys
) {
  discountNodes(
    first: $first
    last: $last
    after: $after
    before: $before
    query: $query
    reverse: $reverse
    sortKey: $sortKey
  ) {
    edges {
      cursor
      node {
        id
        discount {
          __typename
          ... on DiscountAutomaticApp {
            discountId
            title
            status
            combinesWith {
              orderDiscounts
              productDiscounts
              shippingDiscounts
            }
            discountClasses
            startsAt
            endsAt
          }
        }
      }
    }
    nodes {
      id
      discount {
        __typename
        ... on DiscountAutomaticApp {
          discountId
          title
          status
        }
        ... on DiscountAutomaticBasic {
          title
          status
          startsAt
          endsAt
        }
      }
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
  }
}
